test('reviews store Draft v2 with read-only context through edit, analysis and adoption, and review edits bind to the last administrator change', async () => {
    let review = await create(); const id = review.item.id, _id = new ObjectId(id);
    assert.equal((await importCollection().findOne({ _id }))!.draftVersion, 2);
    review = await edit(review, draft => { draft.album.title = 'Edited title'; });
    review = await analyzeCatalogReview(String(actor), id, mutation(review.item.revision), provider);
    // A worker tick advances the revision without an administrator receipt, so a save at the revision last seen still succeeds.
    await runAdminImportWorkerOnce(provider);
    assert.ok((await current(id)).item.revision > review.item.revision);
    const duringAnalysis = await edit(review, draft => { draft.tracks[1].title = 'Saved during analysis'; });
    assert.deepEqual([duringAnalysis.receipt!.kind, duringAnalysis.item.draft.tracks[1].title], ['edit', 'Saved during analysis']);
    await runAdminImportWorkerOnce(provider);
    review = await current(id); const [suggestion] = review.item.suggestions;
    assert.equal(review.item.analysis.state, 'complete');
    const adoptBody = { ...mutation(review.item.revision), generation: 1, selectedIds: [suggestion.id], rejectIds: [] };
    review = await adoptCatalogReview(String(actor), id, adoptBody);
    assert.equal(review.item.draft.album.title, 'Proposed Album');
    assert.deepEqual(await adoptCatalogReview(String(actor), id, adoptBody), review, 'a replay returns the stored response');
    // Reviews are stored as Draft v2 with no value origins: only administrators write their drafts.
    const doc = await importCollection().findOne({ _id });
    assert.deepEqual([doc!.draftVersion, 'draftOrigins' in doc!], [2, false]);
    for (const draft of [doc!.draft, doc!.analysis.baseline!]) {
        assert.deepEqual(Object.keys(draft.album).sort(), ['artists', 'label', 'releaseDate', 'title', 'visibility']);
        assert.equal(draft.tracks.every(track => 'discNumber' in track), true);
    }
    assert.deepEqual(doc!.suggestions.map(value => value.field), ['title']);
    // An edit from before another administrator change, or from a revision never issued, is refused even though it changes another
    // value, and a field-patch body is not a review edit.
    const stale = { ...review.item.draft, tracks: review.item.draft.tracks.map((track, index) => index ? track : { ...track, title: 'Another value' }) };
    for (const revision of [review.item.revision - 1, review.item.revision + 1]) await assert.rejects(editCatalogReview(String(actor), id, { ...mutation(revision), draft: stale }), code('ADMIN_IMPORT_REVISION_CONFLICT'));
    await assert.rejects(async () => editCatalogReview(String(actor), id, { ...mutation(review.item.revision), changes: [{ path: 'album.title', base: 'Proposed Album', value: 'Patched' }] }), code('ADMIN_IMPORT_INVALID_INPUT'));
    // A v1 draft comes from an editor predating Draft v2 reviews: a reload request, even at a stale revision, with no write.
    const v1 = { album: { title: 'v1 title', artistName: 'Existing Artist', releaseDate: null, visibility: 'hidden' }, tracks: review.item.draft.tracks.map(({ slotId, title, trackNumber }) => ({ slotId, title, trackNumber })) };
    for (const revision of [review.item.revision, review.item.revision - 1]) await assert.rejects(editCatalogReview(String(actor), id, { ...mutation(revision), draft: v1 }), code('ADMIN_IMPORT_RELOAD_REQUIRED'));
    const edited = await edit(review, draft => { draft.album.title = 'Replayed title'; });
    const editBody = { ...mutation(edited.item.revision), draft: { ...edited.item.draft, album: { ...edited.item.draft.album, title: 'Another title' } } };
    const saved = await editCatalogReview(String(actor), id, editBody); assert.deepEqual(await editCatalogReview(String(actor), id, editBody), saved);
    await assert.rejects(editCatalogReview(String(actor), id, { ...editBody, draft: { ...editBody.draft, album: { ...editBody.draft.album, title: 'Changed intent' } } }), code('ADMIN_IMPORT_OPERATION_CONFLICT'));
    const final = await importCollection().findOne({ _id }); assert.equal(final!.revision, saved.item.revision); assert.equal((final!.draft as typeof saved.item.draft).album.title, 'Another title');
});

