test('applying a captured Disc Number writes it as a catalog edit, re-derives the order and commits with the receipt; null clears both keys', async () => {
    await db().collection('audioTracks').updateOne({ _id: first }, { $set: { discNumber: 1, discNumberSource: 'embedded' } });
    let review = await create(); assert.deepEqual(review.item.source.tracks.map(track => track.discNumber), [1, null]);
    review = await edit(review, draft => { draft.tracks[0].discNumber = 2; draft.tracks[1].discNumber = 1; });
    const discs: CatalogReviewField[] = review.item.source.tracks.map(track => ({ scope: 'track', slotId: track.slotId, field: 'discNumber' }));
    const body = { ...mutation(review.item.revision), fields: discs }, result = await applyCatalogReview(String(actor), review.item.id, body);
    assert.deepEqual([result.item.state, result.receipt!.kind, result.item.applied!.fields], ['applied', 'apply', discs]);
    const [firstTrack, secondTrack] = await Promise.all([first, second].map(id => db().collection('audioTracks').findOne({ _id: id })));
    assert.deepEqual([firstTrack!.discNumber, firstTrack!.discNumberSource, secondTrack!.discNumber, secondTrack!.discNumberSource, firstTrack!.trackNumber], [2, 'admin-catalog', 1, 'admin-catalog', 1]);
    assert.deepEqual((await db().collection('albums').findOne({ _id: album }))!.audioTrackIds, [String(second), String(first)]);
    assert.deepEqual(await applyCatalogReview(String(actor), review.item.id, body), result);
    await assert.rejects(applyCatalogReview(String(actor), review.item.id, { ...body, fields: [discs[0]] }), code('ADMIN_IMPORT_OPERATION_CONFLICT'));
    // A later review captures the applied discs and clears one: both keys are removed and the Track orders as disc 1 again.
    let next = await create(); assert.deepEqual(next.item.source.tracks.map(track => track.discNumber), [1, 2]);
    assert.deepEqual(next.item.source.tracks.map(track => track.id), [String(second), String(first)]);
    next = await edit(next, draft => { draft.tracks[1].discNumber = null; });
    await applyCatalogReview(String(actor), next.item.id, { ...mutation(next.item.revision), fields: [{ scope: 'track', slotId: next.item.source.tracks[1].slotId, field: 'discNumber' }] });
    const cleared = await db().collection('audioTracks').findOne({ _id: first });
    assert.deepEqual(['discNumber' in cleared!, 'discNumberSource' in cleared!], [false, false]);
    assert.deepEqual((await db().collection('albums').findOne({ _id: album }))!.audioTrackIds, [String(first), String(second)]);
});

