test('an oversized review draft is refused at creation and nothing is inserted; the read-only Credits context never counts toward the cap', async () => {
    const ids = Array.from({ length: 60 }, () => new ObjectId());
    await db().collection('audioTracks').insertMany(ids.map((id, index) => ({ _id: id, title: '题'.repeat(300), trackNumber: index + 1, uploadStatus: 'ready', publicationStatus: 'ready', s3Key: String(id), albumId: String(album), visibility: 'public', mediaType: 'audio' })));
    await db().collection('albums').updateOne({ _id: album }, { $set: { audioTrackIds: ids.map(String) } });
    await assert.rejects(create(), code('ADMIN_IMPORT_INVALID_INPUT'));
    assert.equal(await importCollection().countDocuments({}), 0);
    // 20 long Artist Credits push the whole draft past 48 KB while its editable values stay under it: creation and a growing edit
    // within the editable cap are admitted, because the administrator cannot shorten that context from the review.
    const artists = Array.from({ length: 20 }, (_, index) => ({ _id: new ObjectId(), name: `${'题'.repeat(196)} ${String(index).padStart(3, '0')}`, lifecycleStatus: 'ready' }));
    await db().collection('artists').insertMany(artists);
    await db().collection('audioTracks').updateMany({ _id: { $in: ids.slice(44, 50) } }, { $set: { title: 'Short title' } });
    await db().collection('albums').updateOne({ _id: album }, { $set: { audioTrackIds: ids.slice(0, 50).map(String), credits: artists.map((value, order) => ({ creditId: `artist_${order}`, subjectType: 'artist', subjectId: String(value._id), role: 'primary', order, joinPhrase: ' & ' })) } });
    let review = await create(); const draft = review.item.draft, capped = { ...draft, album: { ...draft.album, artists: [], label: null } };
    assert.equal(draft.album.artists.length, 20);
    assert.ok(draftBytes(draft) > 48_000 && draftBytes(capped) < 47_000, `${draftBytes(draft)} / ${draftBytes(capped)}`);
    // Adopting a longer suggested title and a growing edit stay admitted while the editable values fit.
    const longTitle: ImportAnalysisProvider = { configured: () => true, analyze: async input => input.album ? [{ scope: 'album', slotId: null, field: 'title', baseline: input.baseline.album.title, value: '题'.repeat(300), source: 'context', evidence: 'Existing title' }] : [] };
    review = await analyzeCatalogReview(String(actor), review.item.id, mutation(review.item.revision), longTitle);
    for (let tick = 0; tick < 5 && (await current(review.item.id)).item.analysis.state !== 'complete'; tick++) await runAdminImportWorkerOnce(longTitle);
    review = await current(review.item.id);
    review = await adoptCatalogReview(String(actor), review.item.id, { ...mutation(review.item.revision), generation: 1, selectedIds: [review.item.suggestions[0].id], rejectIds: [] });
    review = await edit(review, value => { value.tracks[44].title = '题'.repeat(300); });
    assert.deepEqual([review.item.draft.album.title, review.item.draft.tracks[44].title], ['题'.repeat(300), '题'.repeat(300)]);
    const grown = await importCollection().findOne({ _id: new ObjectId(review.item.id) });
    await assert.rejects(edit(review, value => { for (const track of value.tracks) track.title = '题'.repeat(300); }), code('ADMIN_IMPORT_INVALID_INPUT'));
    assert.deepEqual(await importCollection().findOne({ _id: new ObjectId(review.item.id) }), grown);
});

