/** Rewrites a review as one stored before Draft v2 reviews: no draftVersion, a v1 draft and baseline, a v1 Artist suggestion and no captured discs. */
async function downgrade(result: CatalogReviewResponse) {
    const _id = new ObjectId(result.item.id), saved = (await importCollection().findOne({ _id }))!, draft = saved.draft as CatalogReviewResponse['item']['draft'];
    const v1 = { album: { title: draft.album.title, artistName: 'Existing Artist', releaseDate: draft.album.releaseDate, visibility: draft.album.visibility }, tracks: draft.tracks.map(({ slotId, title, trackNumber }) => ({ slotId, title, trackNumber })) };
    const suggestion = { id: 'a'.repeat(24), generation: 1, scope: 'album', slotId: null, field: 'artistName', baseline: 'Existing Artist', value: 'Existing Artist (corrected)', source: 'context', evidence: 'Existing title', decision: 'pending' };
    await importCollection().updateOne({ _id }, { $unset: { draftVersion: '' }, $set: { draft: v1, 'catalogSource.tracks': saved.catalogSource!.tracks.map(({ discNumber: _disc, ...track }) => track), suggestions: [suggestion],
        analysis: { ...saved.analysis, state: 'complete', generation: 1, baseline: structuredClone(v1) } } } as any);
    return { _id, v1 };
}
test('a review stored before Draft v2 reviews opens converted, stays unconverted on reads, refusals and cancellation, and converts at its first change', async () => {
    const createdWith = await createBody(), a = await createCatalogReview(String(actor), createdWith), { _id, v1 } = await downgrade(a), id = a.item.id;
    const legacyEntry = { key: legacyArtistEntryKey(id), name: 'Existing Artist', role: 'primary', joinPhrase: null, musicBrainzId: null };
    const stored = await importCollection().findOne({ _id });
    // A create replay returns the stored review, shown converted.
    assert.deepEqual((await createCatalogReview(String(actor), createdWith)).item.draft.album.artists, [legacyEntry]);
    let review = await current(id);
    assert.deepEqual(review.item.draft.album, { title: 'Existing Album', artists: [legacyEntry], label: null, releaseDate: { year: 2020, month: null, day: null }, visibility: 'hidden' });
    assert.deepEqual(review.item.draft.tracks.map(track => track.discNumber), [null, null]);
    assert.equal(review.item.source.tracks.some(track => 'discNumber' in track), false);
    assert.deepEqual([review.item.suggestions[0].field, review.item.suggestions[0].baseline], ['artists', [legacyEntry]]);
    assert.equal(review.item.capabilities.apply, true);
    // A v1 save asks for a reload and a changed context is invalid; neither converts or writes anything.
    await assert.rejects(editCatalogReview(String(actor), id, { ...mutation(review.item.revision), draft: { ...v1, album: { ...v1.album, title: 'v1 save' } } }), code('ADMIN_IMPORT_RELOAD_REQUIRED'));
    const response = await request(`/catalog-reviews/${id}`, 'PATCH', { ...mutation(review.item.revision), draft: v1 });
    assert.equal(response.status, 409); assert.deepEqual(await response.json(), { code: 'ADMIN_IMPORT_RELOAD_REQUIRED' });
    await assert.rejects(edit(review, draft => { draft.album.artists = []; }), code('ADMIN_IMPORT_INVALID_INPUT'));
    await assert.rejects(adoptCatalogReview(String(actor), id, { ...mutation(review.item.revision), generation: 1, selectedIds: ['a'.repeat(24)], rejectIds: [] }), code('ADMIN_IMPORT_INVALID_INPUT'));
    assert.deepEqual(await importCollection().findOne({ _id }), stored);
    // Stopping analysis never converts.
    review = await cancelCatalogReviewAnalysis(String(actor), id, mutation(review.item.revision));
    let doc = await importCollection().findOne({ _id }); assert.deepEqual(['draftVersion' in doc!, doc!.draft], [false, v1]);
    // An uncaptured disc cannot be applied: no receipt and no catalog write.
    const albumBefore = await db().collection('albums').findOne({ _id: album }), tracksBefore = await db().collection('audioTracks').find({}).sort({ _id: 1 }).toArray();
    await assert.rejects(apply(review, [{ scope: 'track', slotId: review.item.source.tracks[0].slotId, field: 'discNumber' }]), code('ADMIN_IMPORT_INVALID_INPUT'));
    assert.deepEqual(await db().collection('albums').findOne({ _id: album }), albumBefore); assert.deepEqual(await db().collection('audioTracks').find({}).sort({ _id: 1 }).toArray(), tracksBefore);
    doc = await importCollection().findOne({ _id }); assert.deepEqual([doc!.revision, 'draftVersion' in doc!], [review.item.revision, false]);
    // An uncaptured disc cannot be saved either: invalid input, with no conversion and no write.
    const unconverted = await importCollection().findOne({ _id });
    await assert.rejects(edit(review, draft => { draft.album.title = 'Converted title'; draft.tracks[0].discNumber = 4; }), code('ADMIN_IMPORT_INVALID_INPUT'));
    assert.deepEqual(await importCollection().findOne({ _id }), unconverted);
    // The first admitted edit stores Draft v2: the legacy entry, its baseline and suggestion, no origins and an untouched source.
    review = await edit(review, draft => { draft.album.title = 'Converted title'; });
    doc = await importCollection().findOne({ _id });
    assert.equal(doc!.draftVersion, 2); assert.equal('draftOrigins' in doc!, false);
    assert.deepEqual((doc!.draft as typeof review.item.draft).album.artists, [legacyEntry]); assert.deepEqual((doc!.analysis.baseline as typeof review.item.draft).album.artists, [legacyEntry]);
    assert.deepEqual(doc!.suggestions.map(value => value.field), ['artists']); assert.deepEqual(doc!.catalogSource, stored!.catalogSource);
    assert.deepEqual(review.item.draft.tracks.map(track => track.discNumber), [null, null]);
    // A title still applies; an uncaptured disc never does.
    await assert.rejects(apply(review, [albumTitle, { scope: 'track', slotId: review.item.source.tracks[0].slotId, field: 'discNumber' }]), code('ADMIN_IMPORT_INVALID_INPUT'));
    review = await apply(review); assert.equal(review.item.state, 'applied');
    assert.equal((await db().collection('albums').findOne({ _id: album }))!.title, 'Converted title'); assert.equal('discNumber' in (await db().collection('audioTracks').findOne({ _id: first }))!, false);
    // Adopting on a v1 review converts it too.
    const b = await create(); await downgrade(b);
    const rejected = await adoptCatalogReview(String(actor), b.item.id, { ...mutation(b.item.revision), generation: 1, selectedIds: [], rejectIds: ['a'.repeat(24)] });
    assert.equal(rejected.item.suggestions[0].decision, 'rejected'); assert.equal((await importCollection().findOne({ _id: new ObjectId(b.item.id) }))!.draftVersion, 2);
    // An old applied review opens read-only.
    const { _id: appliedId } = await downgrade(review);
    const old = await current(review.item.id);
    assert.deepEqual([old.item.state, old.item.capabilities, old.item.applied!.fields], ['applied', { analysis: false, apply: false }, [albumTitle]]);
    await assert.rejects(edit(old, draft => { draft.album.title = 'After apply'; }), code('ADMIN_CATALOG_REVIEW_APPLIED'));
    const appliedDoc = await importCollection().findOne({ _id: appliedId });
    await assert.rejects(editCatalogReview(String(actor), review.item.id, { ...mutation(old.item.revision), draft: v1 }), code('ADMIN_IMPORT_RELOAD_REQUIRED'));
    assert.deepEqual(await importCollection().findOne({ _id: appliedId }), appliedDoc);
});

test('creation from a stale Album revision is a source change that inserts nothing, so the operation can be retried at the current revision', async () => {
    const body = await createBody();
    await db().collection('albums').updateOne({ _id: album }, { $set: { title: 'Changed before creation' } });
    await assert.rejects(createCatalogReview(String(actor), body), code('ADMIN_CATALOG_REVIEW_SOURCE_CHANGED'));
    assert.equal(await importCollection().countDocuments({}), 0);
    const retried = await createCatalogReview(String(actor), { ...body, expectedRevision: (await createBody()).expectedRevision });
    assert.deepEqual([retried.item.source.album.title, retried.item.draft.album.title, retried.receipt!.kind], ['Changed before creation', 'Changed before creation', 'create']);
});

test('an edit that grows a review draft past 48 KB is refused and writes nothing; an oversized stored draft still accepts edits that do not grow it', async () => {
    const ids = Array.from({ length: 60 }, () => new ObjectId());
    await db().collection('audioTracks').insertMany(ids.map((id, index) => ({ _id: id, title: `Track ${index + 1}`, trackNumber: index + 1, uploadStatus: 'ready', publicationStatus: 'ready', s3Key: String(id), albumId: String(album), visibility: 'public', mediaType: 'audio' })));
    await db().collection('albums').updateOne({ _id: album }, { $set: { audioTrackIds: ids.map(String) } });
    let review = await create(); const _id = new ObjectId(review.item.id), before = await importCollection().findOne({ _id });
    await assert.rejects(edit(review, draft => { for (const track of draft.tracks) track.title = '题'.repeat(300); }), code('ADMIN_IMPORT_INVALID_INPUT'));
    assert.deepEqual(await importCollection().findOne({ _id }), before);
    // A draft stored over the cap (for example under an earlier limit) is never locked: a shrinking edit is admitted, a growing one is not.
    await importCollection().updateOne({ _id }, { $set: { 'draft.tracks.$[].title': '题'.repeat(300) } });
    review = await edit(await current(review.item.id), draft => { draft.tracks[0].title = 'Shorter title'; });
    assert.deepEqual([review.item.revision, review.item.draft.tracks[0].title], [2, 'Shorter title']);
    const shrunk = await importCollection().findOne({ _id });
    await assert.rejects(edit(review, draft => { draft.tracks[0].title = '题'.repeat(300); draft.album.title = '题'.repeat(300); }), code('ADMIN_IMPORT_INVALID_INPUT'));
    assert.deepEqual(await importCollection().findOne({ _id }), shrunk);
});

test('a pre-Draft v2 review refuses label and visibility edits unconverted, converts once under concurrent edits, and converts when analysis or apply is its first change', async () => {
    const artistProvider: ImportAnalysisProvider = { configured: () => true, analyze: async input => input.album ? [{ scope: 'album', slotId: null, field: 'artistName', baseline: input.baseline.album.artistName, value: 'Synthetic Luna Artist', source: 'context', evidence: 'Existing title' }] : [] };
    const entry = (id: string) => ({ key: legacyArtistEntryKey(id), name: 'Existing Artist', role: 'primary', joinPhrase: null, musicBrainzId: null });
    const a = await create(), { _id } = await downgrade(a), stored = await importCollection().findOne({ _id });
    let review = await current(a.item.id);
    for (const change of [
        (draft: CatalogReviewResponse['item']['draft']) => { draft.album.label = { name: 'Synthetic Label', musicBrainzId: null }; },
        (draft: CatalogReviewResponse['item']['draft']) => { draft.album.visibility = 'public'; }
    ]) await assert.rejects(edit(review, change), code('ADMIN_IMPORT_INVALID_INPUT'));
    assert.deepEqual(await importCollection().findOne({ _id }), stored);
    // Two concurrent first edits: one wins and stores Draft v2 once; the other writes nothing.
    const edits = await Promise.allSettled([edit(review, draft => { draft.album.title = 'A'; }), edit(review, draft => { draft.album.title = 'B'; })]);
    assert.equal(edits.filter(value => value.status === 'fulfilled').length, 1);
    const converted = await importCollection().findOne({ _id });
    assert.deepEqual([converted!.draftVersion, converted!.revision, converted!.receipts.length], [2, stored!.revision + 1, stored!.receipts.length + 1]);
    assert.deepEqual([(converted!.draft as typeof review.item.draft).album.artists, converted!.suggestions.map(value => value.field)], [[entry(a.item.id)], ['artists']]);
    // Analysis as the first change converts before its baseline is frozen; Luna's Artist name is then compared with the legacy entry.
    const b = await create(), { _id: bId } = await downgrade(b);
    await analyzeCatalogReview(String(actor), b.item.id, mutation(b.item.revision), artistProvider);
    const analyzed = await importCollection().findOne({ _id: bId });
    assert.equal(analyzed!.draftVersion, 2); assert.deepEqual((analyzed!.analysis.baseline as typeof review.item.draft).album.artists, [entry(b.item.id)]);
    await runAdminImportWorkerOnce(artistProvider); await runAdminImportWorkerOnce(artistProvider);
    review = await current(b.item.id);
    assert.deepEqual(review.item.suggestions.map(value => [value.field, value.baseline, (value.value as { name: string }[]).map(item => item.name)]), [['artists', [entry(b.item.id)], ['Synthetic Luna Artist']]]);
    // A direct apply as the first change converts too, and applies the saved title.
    const c = await create(), { _id: cId } = await downgrade(c);
    await importCollection().updateOne({ _id: cId }, { $set: { 'draft.album.title': 'Legacy private title' } });
    review = await apply(await current(c.item.id)); assert.equal(review.item.state, 'applied');
    const appliedDoc = await importCollection().findOne({ _id: cId });
    assert.deepEqual([appliedDoc!.draftVersion, (appliedDoc!.draft as typeof review.item.draft).album.title], [2, 'Legacy private title']);
    assert.equal((await db().collection('albums').findOne({ _id: album }))!.title, 'Legacy private title');
});

test('a pre-Draft v2 review whose analysis was queued before deploy converts at a later edit and the worker then suggests against the legacy entry', async () => {
    let review = await create(); const id = review.item.id, _id = new ObjectId(id);
    review = await analyzeCatalogReview(String(actor), id, mutation(review.item.revision), { configured: () => true, analyze: async () => [] });
    // Rewrite it as format 1 with its analysis still queued: a v1 draft and baseline, pending chunks and no captured discs.
    const saved = (await importCollection().findOne({ _id }))!, draft = saved.draft as CatalogReviewResponse['item']['draft'];
    const v1 = { album: { title: draft.album.title, artistName: 'Existing Artist', releaseDate: draft.album.releaseDate, visibility: draft.album.visibility }, tracks: draft.tracks.map(({ slotId, title, trackNumber }) => ({ slotId, title, trackNumber })) };
    await importCollection().updateOne({ _id }, { $unset: { draftVersion: '' }, $set: { draft: v1, 'analysis.baseline': structuredClone(v1), 'catalogSource.tracks': saved.catalogSource!.tracks.map(({ discNumber: _disc, ...track }) => track) } } as any);
    const queued = (await importCollection().findOne({ _id }))!;
    assert.deepEqual([queued.analysis.state, queued.analysis.chunks.every(chunk => chunk.state === 'pending'), 'draftVersion' in queued], ['queued', true, false]);
    // A later edit of an untouched path converts the queued review before the worker runs.
    review = await edit(await current(id), value => { value.tracks[1].title = 'Edited before dispatch'; });
    const converted = (await importCollection().findOne({ _id }))!, legacyEntry = { key: legacyArtistEntryKey(id), name: 'Existing Artist', role: 'primary', joinPhrase: null, musicBrainzId: null };
    assert.deepEqual([converted.draftVersion, converted.analysis.state, (converted.analysis.baseline as typeof review.item.draft).album.artists], [2, 'queued', [legacyEntry]]);
    // The worker dispatches the converted baseline as its v1 view and maps Luna's Artist name onto an entries suggestion.
    const lunaProvider: ImportAnalysisProvider = { configured: () => true, analyze: async input => input.album ? [
        { scope: 'album', slotId: null, field: 'artistName', baseline: input.baseline.album.artistName, value: 'Synthetic Luna Artist', source: 'context', evidence: 'Existing title' },
        { scope: 'album', slotId: null, field: 'title', baseline: input.baseline.album.title, value: 'Proposed Album', source: 'context', evidence: 'Existing title' }] : [] };
    for (let tick = 0; tick < 5 && (await importCollection().findOne({ _id }))!.analysis.state !== 'complete'; tick++) await runAdminImportWorkerOnce(lunaProvider);
    const analyzed = (await importCollection().findOne({ _id }))!;
    assert.deepEqual([analyzed.draftVersion, analyzed.analysis.state, analyzed.suggestions.map(value => value.field)], [2, 'complete', ['artists', 'title']]);
    assert.deepEqual(analyzed.suggestions[0].baseline, [legacyEntry]);
    review = await current(id);
    const title = review.item.suggestions.find(value => value.field === 'title')!;
    review = await adoptCatalogReview(String(actor), id, { ...mutation(review.item.revision), generation: review.item.analysis.generation, selectedIds: [title.id], rejectIds: [] });
    assert.deepEqual([review.item.draft.album.title, review.item.draft.tracks[1].title, review.item.draft.album.artists], ['Proposed Album', 'Edited before dispatch', [legacyEntry]]);
});
